import {VERSIONS,questionSet,validAnswer,scoreProfile,isComplete,rankProfiles,restoreState} from './core.js';
import {drawRadar} from './hero.js';
import {renderResultRadar} from './radar.js';
import {PHOTOS} from './photos.js';
import {responseStats,strongestAxes,comparisonDetails,readingModels,possibleTradeoffs,MODEL_AXES} from './insights.js';
