import {describeCompass} from './compass.js';
import {renderSpectrum,renderSpectrumView} from './spectrum.js';
const app=document.querySelector('#app'),homeHTML=app.innerHTML,KEY='uruguay-compass-v2',OLD_KEY='uruguay-compass-v1',ARCHIVE_KEY='uruguay-compass-v1-archive';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
let state=null,storageOK=true,theme='light',selectedVersion='short',autoAdvance=false;
const spectrumState={query:'',party:'all',selectedId:null};
const rankingCount=FIGURES.filter(f=>f.rankEligible).length;
let resultReferenceId=null,stopResultTracking=()=>{};
try{const saved=localStorage.getItem(KEY),previous=saved===null?localStorage.getItem(OLD_KEY):null;state=restoreState(saved??previous,QUESTIONS);if(previous&&state){const archived=localStorage.getItem(ARCHIVE_KEY);if(archived===null)localStorage.setItem(ARCHIVE_KEY,previous);localStorage.setItem(KEY,JSON.stringify(state));if(archived===null||archived===previous)localStorage.removeItem(OLD_KEY)}theme=localStorage.getItem('compass-theme')==='dark'?'dark':'light';autoAdvance=localStorage.getItem('compass-auto-advance')==='true'}catch{storageOK=false}
document.documentElement.dataset.theme=theme;
const announce=t=>{document.querySelector('#announcement').textContent=t};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageOK=false;announce('No se pudo guardar. Podés seguir, pero el avance se pierde al cerrar.')}}
function go(route){if(location.hash===`#${route}`)render();else location.hash=route}
function profile(){return state&&isComplete(questionSet(QUESTIONS,state.version),state.answers)?scoreProfile(questionSet(QUESTIONS,state.version),state.answers):null}
const sourceList=s=>`<ul class="sources">${(s||[]).map(x=>`<li>${link(x.url,x.title)}</li>`).join('')}</ul>`;
function portrait(e){const p=PHOTOS[e.id];return p?`<figure class="portrait">${p.crop?`<span class="portrait-window" style="${portraitStyle(p)}">`:""}<img src="${esc(p.src)}" alt="Retrato de ${esc(e.name)}" width="200" height="240" loading="lazy">${p.crop?"</span>":""}<figcaption>${link(p.source,photoCredit(p))}</figcaption></figure>`:e.photoUnavailable?`<figure class="portrait portrait-placeholder"><div aria-hidden="true">${esc(e.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><figcaption>${esc(e.photoUnavailable)}</figcaption></figure>`:''}
const secondary=(a,t)=>`<button class="secondary" data-action="${a}">${t}</button>`;
const themeGraphic=()=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${theme==='dark'?'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>':'<path d="M20.5 14A9 9 0 0 1 10 3.5 9 9 0 1 0 20.5 14Z"/>'}</svg>`;
const themeButton=()=>`<button type="button" class="icon-button" data-action="theme" aria-label="${theme==='dark'?'Activar modo claro':'Activar modo oscuro'}" title="${theme==='dark'?'Activar modo claro':'Activar modo oscuro'}">${themeGraphic()}</button>`;
function header(test=false){return `<header class="app-header"><a class="app-brand" href="#inicio"><img src="sun.svg" width="36" height="36" alt=""><strong>Uruguay Compass</strong></a><nav aria-label="${test?'Controles del test':'Principal'}"${test?' class="test-header-controls"':''}>${test?themeButton()+`<button type="button" class="icon-button" data-action="reset" aria-label="Reiniciar el test" title="Reiniciar el test"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/></svg></button>`:'<a href="#enciclopedia">Enciclopedia</a><a href="#metodologia">Metodología</a><a href="#faq">Ayuda</a>'+themeButton()}</nav></header>`}
function shell(title,body,wide=false,test=false){stopResultTracking();app.innerHTML=header(test)+`<main id="main" class="page ${wide?'wide':''}" tabindex="-1"><h1>${title}</h1>${body}</main><footer class="app-footer"><span>Educativo. Sin validación científica ni recomendación de voto.</span><a href="#correcciones">Señalar un error</a><a href="#privacidad">Privacidad</a></footer>`}
function renderHome(){stopResultTracking();app.innerHTML=homeHTML;app.querySelector('#home-title').innerHTML='¿A qué personaje político<br class="desktop-br"> se acercan <span>tus ideas?</span>';const footer=app.querySelector('.home-footer');footer.insertAdjacentHTML('beforeend',`<div class="home-tools"><a href="#faq">Ayuda</a><a href="#correcciones">Señalar un error</a>${themeButton()}</div>`);if(state?.migrated)app.querySelector('.home-intro').insertAdjacentHTML('beforeend','<p class="notice">Actualizamos los doce ejes. El test anterior se conserva. Mantuvimos las respuestas que siguen vigentes. Completá las preguntas nuevas de Instituciones y Educación y servicios para obtener tu resultado.</p>');if(state)app.querySelector('.home-intro').insertAdjacentHTML('beforeend',`<div class="resume-actions"><a href="#${state.completed?'resultados':'test'}">${state.completed?'Ver mi resultado guardado':'Continuar mi test'}</a>${secondary('reset','Empezar de nuevo')}</div>`);drawRadar(document.querySelector('#home-radar'),[70,48,58,54,44,56,68,75,57,72,63,48]);}
const answerLabels=['Muy en desacuerdo','En desacuerdo','Ni de acuerdo ni en desacuerdo','De acuerdo','Muy de acuerdo'];
function startScreen(){if(state){go(state.completed?'resultados':'test');return}shell('Elegí la duración del test',`<fieldset class="version-choice"><legend class="sr-only">Versiones del test</legend>${Object.entries(VERSIONS).map(([id,v])=>`<label><input type="radio" name="version" value="${id}" ${id===selectedVersion?'checked':''}><span><strong>${v.label}</strong> · ${v.count} preguntas · ${v.minutes} min</span></label>`).join('')}</fieldset><div class="actions"><button class="primary" data-action="start">Empezar el test</button><a href="#inicio">Volver al inicio</a></div>`)}
const quizIcon=kind=>{const paths={"economia":"<path d=\"m3 8 9-5 9 5H3Zm2 3v7m5-7v7m4-7v7m5-7v7M3 21h18M3 18h18\"/>",
 "impuestos":"<ellipse cx=\"9\" cy=\"6\" rx=\"6\" ry=\"3\"/><path d=\"M3 6v5c0 1.7 2.7 3 6 3m-6-3v5c0 1.7 2.7 3 6 3\"/><ellipse cx=\"16\" cy=\"14\" rx=\"5\" ry=\"3\"/><path d=\"M11 14v4c0 1.7 2.2 3 5 3s5-1.3 5-3v-4\"/>",
 "trabajo":"<rect x=\"3\" y=\"7\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"M8 7V4h8v3M3 12c5 3 13 3 18 0m-9 0v4\"/>",
 "seguridad":"<path d=\"M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z\"/><path d=\"m8 12 3 3 5-6\"/>",
 "instituciones":"<path d=\"M12 3v18M5 21h14M4 7h16M7 7l-4 8h8L7 7Zm10 0-4 8h8l-4-8ZM3 15c0 4 8 4 8 0m2 0c0 4 8 4 8 0\"/>",
 "valores":"<circle cx=\"9\" cy=\"7\" r=\"3\"/><path d=\"M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v3\"/>",
 "laicidad":"<path d=\"M9 11h6v10H9zM7 21h10M12 11V8m0-5c-4 4-3 5 0 5s4-1 0-5Z\"/>",
 "comercio":"<circle cx=\"12\" cy=\"12\" r=\"9\"/><ellipse cx=\"12\" cy=\"12\" rx=\"4\" ry=\"9\"/><path d=\"M3 12h18M5 7h14M5 17h14\"/>",
 "exterior":"<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"m16 8-2 6-6 2 2-6 6-2Z\"/>",
 "inmigracion":"<rect x=\"5\" y=\"3\" width=\"14\" height=\"18\" rx=\"2\"/><circle cx=\"12\" cy=\"10\" r=\"4\"/><path d=\"M8 10h8m-4-4c-2 2-2 6 0 8 2-2 2-6 0-8ZM9 18h6\"/>",
 "educacion-servicios":"<path d=\"M12 6c-3-2-6-3-10-2v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-4-1-7 0-10 2Zm0 0v15\"/>",
 "ambiente":"<path d=\"M20 3c-9 0-16 4-16 10a7 7 0 0 0 7 7c6 0 9-8 9-17ZM3 21 15 9m-7 7h6m-4-2V9\"/>",help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 3v.2"/>',agree:'<path d="m6 12 4 4 8-8"/>',disagree:'<path d="m7 7 10 10M17 7 7 17"/>',neutral:'<path d="M6 12h12"/>',back:'<path d="m10 6-6 6 6 6M4 12h16"/>',next:'<path d="m14 6 6 6-6 6M20 12H4"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]}</svg>`};
function testScreen(){
 if(!state){go('inicio');return}if(state.completed){go('resultados');return}
 const qs=questionSet(QUESTIONS,state.version),q=qs[state.cursor],v=state.answers[q.id],axis=AXES[q.axis],answered=Object.keys(state.answers).length,percent=Math.round(answered/qs.length*100);
 shell('Tus ideas, pregunta a pregunta',`
 <div class="test-top"><span>Pregunta <strong>${state.cursor+1} de ${qs.length}</strong></span><span>${percent}% completado</span></div>
 <progress class="sr-only" value="${answered}" max="${qs.length}" aria-label="Preguntas respondidas"></progress>
 <div class="question-progress" aria-hidden="true">${Array.from({length:12},(_,i)=>`<span><i style="width:${Math.max(0,Math.min(100,(answered/qs.length*12-i)*100))}%"></i></span>`).join('')}</div>
 <form id="question-form" autocomplete="off">
 <section class="question-card" aria-label="Pregunta actual">
 <span class="question-number" aria-hidden="true">${String(state.cursor+1).padStart(2,'0')}</span>
 <div class="question-meta"><span class="question-axis" data-axis="${axis.slug}" aria-label="Eje: ${esc(axis.name)}">${quizIcon(axis.slug)}${esc(axis.name)}</span><button type="button" class="question-help" data-action="question-context" aria-expanded="false" aria-controls="question-context">${quizIcon('help')}Entender</button></div>
 <div id="question-context" class="question-context" hidden><p>${esc(axis.description)}</p><a href="#eje/${q.axis}">Leer ambas posturas y volver al test</a></div>
 <fieldset><legend class="question">${esc(q.text)}</legend><div class="answers">${[0,1,2,3,4].map(i=>`<label class="answer answer-${i>2?'agree':i<2?'disagree':'neutral'}"><span class="answer-symbol" aria-hidden="true">${quizIcon(i>2?'agree':i<2?'disagree':'neutral')}</span><span class="answer-label">${answerLabels[i]}</span><input type="radio" name="answer" value="${i}" ${v===i?'checked':''}></label>`).join('')}</div></fieldset>
 </section>
 <div class="test-controls"><button type="button" class="secondary" data-action="previous" ${state.cursor===0?'disabled':''}>${quizIcon('back')}Anterior</button><div class="test-options"><button type="button" class="auto-advance" data-action="auto-advance" aria-pressed="${autoAdvance}"><span class="auto-switch" aria-hidden="true"></span><span>Avance automático</span><strong class="sr-only">${autoAdvance?'Activado':'Desactivado'}</strong></button></div><button class="primary" type="submit" ${!validAnswer(v)?'disabled':''}>${state.cursor===qs.length-1?'Ver mi resultado':'Siguiente'}${quizIcon('next')}</button></div>
 </form>
 <p class="small muted test-storage">${storageOK?'Tu avance se guarda solo en este navegador.':'El almacenamiento está bloqueado. Podés seguir, pero no cerrar esta página.'} Podés volver y cambiar cualquier respuesta.</p><a class="quiet-link" href="#inicio">Salir y conservar avance</a>`,false,true);
 document.querySelectorAll('#question-form input[name=answer]').forEach(input=>{input.checked=validAnswer(v)&&Number(input.value)===v});
 document.querySelector('#main').classList.add('questionnaire-page');document.querySelector('#main>h1').classList.add('sr-only');
}
const ranked=()=>rankFigures(profile(),FIGURES,resultReferenceId);
const rankingTie=r=>r.closest.length>1?`<p class="small">Misma afinidad: ${r.closest.map(x=>esc(x.entity.name)).join(' · ')}. El orden no indica mayor cercanía. Quienes comparten un programa tienen los mismos puntajes de referencia.</p>`:'';
const closestPicker=r=>r.closest.length>1?`<label class="closest-reference-picker">Mostrar en la foto y la tarjeta<select id="closest-reference">${r.closest.map(x=>`<option value="${x.entity.id}" ${r.ranked[0].entity.id===x.entity.id?'selected':''}>${esc(x.entity.name)}</option>`).join('')}</select></label>`:'';
function matchRow(x){if(!x)return '';const e=x.entity,photo=portrait(e),context=e.partyName?[...new Set([e.partyName,e.era].filter(Boolean))].join(' · '):e.period||e.era||'';return `<article class="match-row${photo?' match-row--portrait':''}">${photo}<div class="match-copy"><h3><a href="#${e.id.startsWith('partido-')?'partido/'+e.id.slice(8):'ficha/'+e.id}">${esc(e.name)}</a></h3><p class="small">${esc(context)}</p><p>${esc(e.summary)}</p><a href="#comparar/${e.id}">Comparar eje por eje y ver fuentes</a></div><strong class="match-score">${x.score}%<span>coincidencia editorial</span></strong></article>`}
function resultsDashboard(){
 const p=profile();if(!p){shell('Todavía falta tu perfil',`<p>Completá las preguntas para ver tus doce posiciones.</p><a class="primary button-link" href="#${state?'test':'inicio'}">${state?'Continuar':'Elegir un test'}</a>`);return}
 const qs=questionSet(QUESTIONS,state.version),stats=responseStats(qs,state.answers),r=ranked(),top=r.ranked.slice(0,Math.max(3,r.closest.length)),far=r.ranked.at(-1),lead=top[0],strong=strongestAxes(p),models=readingModels(p),tradeoffs=possibleTradeoffs(p),diff=comparisonDetails(p,lead.entity.profile,r.axes);
 const pole=i=>p[i]>50?AXES[i].right:AXES[i].left;
 const position=i=>Math.abs(p[i]-50)<10?'Posición intermedia':pole(i);
 const compassReading=describeCompass(p[0],p[3]);
 const partyRanking=rankProfiles(p,PARTIES).ranked,closestParties=partyRanking.filter(x=>x.score===partyRanking[0].score);
 const sections=[['ideology-panel','Lectura más cercana'],['scale-panel','Cómo leer la escala'],['summary-panel','Lectura general'],['axes-panel','Doce ejes'],['compass-panel','Espectro político'],['priorities-panel','Prioridades'],['models-panel','Lecturas ideológicas'],['figures-panel','Personajes'],['parties-panel','Partidos'],['differences-panel','Coincidencias y diferencias'],['share-panel','Tu tarjeta']];
 const compareBar=x=>`<article class="difference"><div><strong>${esc(AXES[x.axis].name)}</strong><span>Vos ${x.user} · Referencia ${x.reference}</span></div><div class="dual-track"><i style="left:${x.user}%" aria-hidden="true"></i><b style="left:${x.reference}%" aria-hidden="true"></b></div><div class="pole-labels"><span>${esc(AXES[x.axis].left)}</span><span>${esc(AXES[x.axis].right)}</span></div></article>`;
 shell('Tu lectura ideológica más cercana',`<p class="results-intro">${VERSIONS[state.version].label} · ${qs.length} respuestas · Doce dimensiones de tus ideas.</p><p class="small ranking-coverage">Tu resultado se calcula con ${rankingCount} referentes documentados. Las respuestas guardadas también usan esta comparación actualizada.</p><div class="results-layout"><div class="results-content">
 <section class="result-panel closest-ideology" id="ideology-panel"><div class="ideology-copy"><h2>${esc(models[0].name)}</h2><p class="ideology-proximity"><strong>${models[0].score}<span>/100</span></strong> de similitud con este modelo</p><h3>¿Qué propone este modelo?</h3><p>${esc(models[0].text)}</p><p class="small">Es la lectura más cercana entre los cinco modelos pedagógicos de esta edición, calculada sobre cuatro ejes. No define tu identidad política ni recomienda un voto.</p>${models.filter(m=>m.score===models[0].score).length>1?`<p class="small">Hay empate con ${models.filter(m=>m.score===models[0].score&&m.id!==models[0].id).map(m=>esc(m.name)).join(', ')}. El orden entre modelos empatados es convencional.</p>`:''}<a href="#resultados" data-jump="models-panel">Comparar las cinco lecturas y ver el cálculo</a></div><aside class="closest-person" aria-label="Personaje más cercano"><h3>${r.closest.length>1?'Referentes más cercanos (empate)':'Personaje más cercano'}</h3>${portrait(lead.entity)}<h4>${esc(lead.entity.name)}</h4><p><strong>${lead.score}%</strong> de coincidencia editorial</p><p class="small">${esc(lead.entity.comparisonLabel)} · cuatro ejes comunes. Es una comparación distinta de la del modelo ideológico.</p>${rankingTie(r)}${closestPicker(r)}<a href="#comparar/${lead.entity.id}">Ver coincidencias y diferencias</a></aside></section>
 <section class="result-panel scale-explainer" id="scale-panel"><h2>Cómo leer tus porcentajes</h2><p>El porcentaje se acompaña del nombre del polo predominante. Por ejemplo, <strong>70% Libre mercado</strong> indica una inclinación hacia el mercado; <strong>70% Intervencionismo estatal</strong>, hacia un papel más activo del Estado.</p><div class="scale-legend" aria-label="Ejemplos de lectura del eje Economía"><div><strong>70% Intervencionismo estatal</strong><span>Hacia el Estado</span></div><div><strong>Equilibrado</strong><span>Cerca del centro</span></div><div><strong>70% Libre mercado</strong><span>Hacia el mercado</span></div></div><p class="small">Son posiciones entre los polos de cada eje, <strong>no etiquetas políticas</strong>, porcentajes de acuerdo con todas las propuestas ni medidas de convicción. Entre 41 y 59 en la escala original se muestra «Equilibrado», con el mismo criterio de lectura intermedia del test. El radar y las comparaciones detalladas conservan esa escala original.</p></section>
 <section class="result-panel profile-reading" id="summary-panel"><h2>Una lectura de tus respuestas</h2><p class="profile-statement">${strong.length?`Tus inclinaciones más marcadas se orientan hacia ${strong.slice(0,3).map(x=>`<strong>${esc(pole(x.axis).toLocaleLowerCase('es'))}</strong>`).join(', ')}.`:'Tus puntajes se ubican cerca del centro en los doce ejes.'}</p><p>Esta descripción surge de tus puntajes. No define tu identidad política ni anticipa tu voto.</p><div class="reading-facts"><span>${qs.length} afirmaciones</span><span>${stats.reduce((s,x)=>s+x.neutral,0)} respuestas neutras</span><span>${strong.length} ejes con inclinación ≥10 puntos</span></div><details><summary>Cómo se construye esta lectura</summary><p>Se ordenan los ejes por distancia al centro (50) y se describen hasta tres con una diferencia de al menos 10 puntos. Los empates siguen el orden de los ejes. Un puntaje intermedio puede resultar de respuestas neutras o de posiciones en ambos sentidos; no permite atribuir una ideología por sí solo.</p></details></section>
 <section class="result-panel" id="axes-panel"><h2>Tus doce ejes</h2><div class="axes-grid">${AXES.map((a,i)=>`<article class="axis-tile">${renderAxisSummary(a,p[i])}</article>`).join('')}</div><details class="radar-details"><summary>Ver la escala original como radar</summary>${renderResultRadar(p,AXES)}</details></section>
 <section class="result-panel compass-panel spectrum-panel" id="compass-panel"><h2>Tu lugar en el espectro político</h2><p class="section-description">Explorá dónde quedan tus respuestas frente a los referentes de distintos períodos. Este mapa compara economía y seguridad.</p><div class="spectrum-user-reading"><h3>${esc(compassReading.title)}</h3><p>${esc(compassReading.text)}</p><p class="spectrum-user-coordinates"><span>Tu economía <strong>${p[0]}/100</strong></span><span>Tu seguridad <strong>${p[3]}/100</strong></span></p></div>${renderSpectrum(p,FIGURES,{...spectrumState,selectedId:spectrumState.selectedId||lead.entity.id})}<details><summary>Cómo se ubican los referentes</summary><p>Los puntos son estimaciones editoriales basadas en los documentos enlazados, no mediciones de las personas. En las candidaturas se usa el programa de la elección indicada; en otras referencias, medidas de gobierno o declaraciones públicas del período señalado. Dos integrantes de una fórmula pueden compartir coordenadas sin pensar igual en todo. Las referencias de distintos períodos no tienen idéntica cobertura.</p><p>Todos los referentes del catálogo tienen evidencia en los cuatro temas comunes. Los demás ejes sin datos no se completan con 50. Las cifras orientan la lectura; no tienen precisión científica. El mapa no mide autoritarismo ni resume los otros diez ejes. El ranking incluye ${rankingCount} referentes: programas electorales de 2009 a 2024 y medidas de los gobiernos de Sanguinetti (1995–2000) y Jorge Batlle (2000–2005), y declaraciones públicas de Bergara (2024) y Andrade (2016–2019), sobre cuatro temas comunes. La comparación entre partidos conserva seis programas de 2024.</p></details></section>
 <section class="result-panel" id="priorities-panel"><h2>Prioridades expresadas</h2><p class="section-description">Una lectura directa de seis temas. Los términos describen las respuestas, no valores personales permanentes.</p><div class="priorities-grid">${[0,2,3,5,9,11].map(i=>`<article><h3>${esc(AXES[i].name)}</h3><p>${esc(position(i))}</p><details><summary>Por qué aparece</summary><p>${p[i]} / 100 entre ${esc(AXES[i].left)} y ${esc(AXES[i].right)}. Se considera intermedio si está a menos de 10 puntos del centro.</p></details></article>`).join('')}</div></section>
 <section class="result-panel" id="models-panel"><h2>Lecturas ideológicas para explorar</h2><p>Estos son <strong>prototipos pedagógicos propios</strong>, no mediciones de corrientes reales ni etiquetas asignadas a tu persona. Comparan únicamente economía, impuestos, trabajo y valores sociales.</p>${models.map(m=>`<article class="model-row"><div><h3>${esc(m.name)}</h3><strong>${m.score}<small>/100 de cercanía al modelo</small></strong></div><meter min="0" max="100" value="${m.score}" aria-label="Cercanía al modelo ${esc(m.name)}">${m.score}</meter><p>${esc(m.text)}</p><details><summary>Ver el modelo y el cálculo</summary><p>${MODEL_AXES.map((i,j)=>`${esc(AXES[i].name)}: ${m.values[j]}`).join(' · ')}.</p><p>Cercanía = 100 menos la diferencia absoluta media con tus cuatro puntajes. Los valores son una rúbrica editorial visible, no datos observados. Una alta cercanía puede coexistir con diferencias grandes en otros temas.</p></details></article>`).join('')}<a href="#glosario">Consultar el significado de los términos</a></section>
 <section class="result-panel" id="figures-panel"><h2>Coincidencias con personajes</h2><p class="lead">${r.closest.length>1?'Las referencias más cercanas a estas respuestas empatan en afinidad.':`En estas respuestas, tu perfil se acerca más al de <strong>${esc(lead.entity.name)}</strong>.`}</p>${rankingTie(r)}${top.map(matchRow).join('')}<h3>La referencia más lejana</h3>${matchRow(far)}<p class="notice">De las ${FIGURES.length} fichas, ${rankingCount} participan en el resultado. La afinidad compara referentes con propuestas documentadas de distintas elecciones sobre los mismos cuatro ejes. No implica pensar igual en todo ni apoyar a un partido. Las fichas sin cobertura suficiente quedan fuera del ranking. Se indica la elección usada en cada caso. Una fórmula puede compartir programa y puntajes: el empate se muestra, no se interpreta como una diferencia personal.</p><p class="small">Los porcentajes empatados se ordenan alfabéticamente, sin indicar mayor cercanía entre ellos.</p><div class="actions"><a href="#comparaciones">Ver todas las comparaciones</a><a href="#figuras">Explorar todos los referentes</a></div></section>
 <section class="result-panel" id="parties-panel"><h2>Comparación con partidos</h2><p>Referencias programáticas de 2024. Pueden coincidir con los porcentajes de sus candidaturas porque utilizan el mismo programa.</p>${rankProfiles(p,PARTIES.map(e=>({...e,id:'partido-'+e.id}))).ranked.map(matchRow).join('')}</section>
 <section class="result-panel" id="differences-panel"><h2>Coincidencias y diferencias</h2><label class="comparison-select">Elegí una referencia<select id="insight-reference">${r.ranked.map(x=>`<option value="${x.entity.id}" ${x.entity.id===lead.entity.id?'selected':''}>${esc(x.entity.name)}</option>`).join('')}</select></label><div id="difference-content"><p>Comparación con <strong>${esc(lead.entity.name)}</strong>. Punto azul: tus respuestas. Círculo vacío: referencia programática.</p><h3>Las distancias más pequeñas</h3>${diff.near.map(compareBar).join('')}<h3>Las distancias más grandes</h3>${diff.far.length?diff.far.map(compareBar).join(''):'<p>Los puntajes coinciden en los cuatro ejes comparados.</p>'}<a href="#comparar/${lead.entity.id}">Ver los doce ejes y sus fuentes</a></div><h3>Ejes con respuestas en ambos sentidos</h3><p>${stats.some(x=>x.left&&x.right)?stats.map((x,i)=>x.left&&x.right?esc(AXES[i].name):null).filter(Boolean).join(' · '):'No aparecen respuestas orientadas a ambos polos dentro de un mismo eje.'}</p><p class="small">Esto puede reflejar distinciones entre propuestas concretas. No es por sí solo un error, falta de información ni incertidumbre.</p><h3>Decisiones que pueden requerir equilibrio</h3>${tradeoffs.length?tradeoffs.map(t=>`<article><h4>${esc(t.title)}</h4><p>${esc(t.text)}</p></article>`).join(''):'<p>Las reglas exploratorias de esta edición no señalan una combinación específica. Eso no demuestra que tus posiciones estén libres de tensiones.</p>'}</section>
 <section class="result-panel" id="share-panel"><h2>Tu tarjeta de resultados</h2><p>Una síntesis visual con tu referencia más cercana, su foto, las otras coincidencias y los doce ejes. Se genera en este dispositivo.</p><div class="card-live-preview"><div class="card-preview-person">${portrait(lead.entity)}<h3>${esc(lead.entity.name)}</h3><p>${lead.score}% de coincidencia editorial</p><p class="small">${esc(lead.entity.comparisonLabel)} · cuatro ejes comunes</p>${r.closest.length>1?`<p class="small card-tie">Comparte la afinidad máxima con ${r.closest.filter(x=>x.entity.id!==lead.entity.id).map(x=>esc(x.entity.name)).join(', ')}.</p>`:''}<div class="card-preview-party"><h4>${closestParties.length>1?'Partidos más cercanos (empate)':'Partido más cercano'}</h4><p class="party-name">${closestParties.map(x=>esc(x.entity.name)).join(' · ')}</p><p><strong>${partyRanking[0].score}%</strong> de coincidencia editorial</p><p class="small">Programas de 2024 · cuatro ejes comunes. No implica apoyo partidario.</p></div></div><div class="card-preview-axes">${AXES.map((a,i)=>`<div><span>${esc(a.short)}</span><meter min="0" max="100" value="${p[i]}" aria-label="${esc(a.name)}">${p[i]}</meter><strong>${p[i]}</strong><small class="mini-poles">0 ${esc(a.left)} → ${esc(a.right)} 100</small></div>`).join('')}</div></div><div class="actions">${secondary('download','Guardar imagen PNG')}${secondary('share','Compartir imagen')}${secondary('reset','Repetir el test')}<a href="#privacidad">Borrar mis datos</a></div><p id="export-status" role="status"></p><canvas id="share-preview" class="share-preview" width="1200" height="1500" hidden aria-label="Vista previa de la imagen generada"></canvas><p class="small">Educativo. Sin validación científica ni recomendación de voto.</p></section>
 </div><aside class="results-index"><nav aria-label="Secciones de mi resultado"><h2>Tu resultado</h2>${sections.map(([id,title])=>`<a href="#resultados" data-jump="${id}">${title}</a>`).join('')}</nav><a href="#metodologia">Método y límites</a></aside></div>`,true);
 document.querySelector('#main').classList.add('results-page');stopResultTracking=trackResultSection(document.querySelector('#main'));
}
function compareScreen(id){const p=profile(),e=[...FIGURES,...PARTIES.map(x=>({...x,id:'partido-'+x.id}))].find(x=>x.id===id);if(!p||!e){shell('Comparación no disponible','<p>Necesitás completar el test y elegir una ficha válida.</p><a href="#resultados">Ir a resultados</a>');return}const common=ranked().axes;shell(`Tus respuestas y ${esc(e.name)}`,`<p>${esc(e.comparisonNote)}</p><p class="notice">Puntajes editoriales de 0 (polo izquierdo) a 100 (derecho). «Sin evidencia» no equivale a 50. Solo los ejes marcados como comunes intervienen en el ranking.</p><div class="table-scroll"><table><caption>Comparación por eje</caption><thead><tr><th>Eje y polos</th><th>Vos</th><th>Referencia</th><th>Fundamento y fuente</th></tr></thead><tbody>${AXES.map((a,i)=>{const ev=e.evidence?.find(v=>v.axis===i),s=ev&&e.sources[ev.source];return `<tr><th>${esc(a.name)}${common.includes(i)?'<small>Común al ranking</small>':''}<small>${esc(a.left)} → ${esc(a.right)}</small></th><td>${p[i]}</td><td>${e.profile[i]===null?'Sin evidencia':e.profile[i]}</td><td>${esc(e.rationale[i])}${s?`<br>${link(s.url,`${s.title}${ev.page?' · p. '+ev.page:''}`)}`:''}</td></tr>`}).join('')}</tbody></table></div><a href="#resultados">Volver a mi resultado</a>`,true)}
function comparisons(){const p=profile();if(!p){go('resultados');return}const a=ranked(),b=rankProfiles(p,PARTIES.map(x=>({...x,id:'partido-'+x.id})));shell('Todas las comparaciones',`<p>Las candidaturas y los partidos pueden coincidir en porcentaje porque se usa el mismo programa como referencia. No es una estimación independiente de cada persona.</p><h2>Candidaturas de distintas elecciones</h2><p>${rankingCount} referentes de distintas elecciones, comparados sobre los mismos cuatro ejes. Los períodos anteriores describen sus programas de entonces; no sus posturas actuales.</p>${a.ranked.map(matchRow).join('')}<h2>Partidos con representación parlamentaria</h2><p class="small">Referencia: programas 2025–2030 y composición parlamentaria al inicio de la legislatura. Fuentes en cada ficha.</p>${b.ranked.map(matchRow).join('')}<a href="#resultados">Volver al resultado</a>`,true)}
function encyclopedia(){shell('Entender la política uruguaya',`<p class="lead">Doce temas, varias posturas. Explorá los debates, las figuras y las palabras detrás del test.</p><nav class="section-nav" aria-label="Secciones de la enciclopedia"><a href="#figuras">Personajes</a><a href="#partidos">Partidos</a><a href="#glosario">Glosario</a><a href="#historia">Historia</a></nav><h2>Los doce ejes</h2><div class="reading-list">${AXES.map(a=>`<a href="#eje/${a.id}"><strong>${esc(a.name)}</strong><span>${esc(a.left)} ↔ ${esc(a.right)}</span></a>`).join('')}</div>`)}
function axisScreen(id){const a=AXES[Number(id)];if(!a){notFound();return}shell(esc(a.name),`<p class="lead">${esc(a.description)}</p><div class="two-poles"><section><h2>${esc(a.left)}</h2><p>${esc(a.leftText)}</p></section><section><h2>${esc(a.right)}</h2><p>${esc(a.rightText)}</p></section></div><h2>Debates en Uruguay</h2><ul>${a.debates.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h2>Para consultar</h2>${sourceList(a.sources)}<div class="actions"><a href="#enciclopedia">Todos los ejes</a>${state&&!state.completed?'<a href="#test">Volver a mi pregunta</a>':''}</div>`)}
function entityList(kind){const es=[...(kind==='partidos'?PARTIES:FIGURES)].sort((a,b)=>a.name.localeCompare(b.name,'es'));shell(kind==='partidos'?'Partidos y sus propuestas':'Personajes y sus propuestas',`<p>${kind==='partidos'?'Las fichas presentan el contexto y las fuentes. Una ubicación editorial no resume una trayectoria completa.':es.length+' referentes que pueden aparecer como resultado. Cada ficha identifica los documentos, el período y las fuentes de los cuatro temas comparados.'}</p><label class="search-label">Buscar por nombre<input type="search" id="entity-search" placeholder="Escribí un nombre" autocomplete="off"></label><div class="reading-list" id="entity-list">${es.map(e=>`<a data-search="${esc((e.name+' '+(e.partyName||'')+' '+(e.aliases||[]).join(' ')).toLocaleLowerCase('es'))}" href="#${kind==='partidos'?'partido':'ficha'}/${e.id}"><strong>${esc(e.name)}${kind==='partidos'?'':`<small class="entity-status">${e.rankEligible?'Disponible como resultado':'Ficha de contexto · fuera del cálculo'}</small>`}</strong><span>${esc(e.era||e.period)} · ${esc(e.partyName||e.short||'')}</span></a>`).join('')}</div><p id="search-empty" hidden>No hay coincidencias. Probá con otra palabra.</p>`)}
function entityScreen(id,party=false){
 const e=(party?PARTIES:FIGURES).find(x=>x.id===id);
 if(!e){notFound();return}
 const hasScores=e.profile.some(Number.isFinite);
 const axes=()=>`<h2>Ubicación y fundamentos</h2>${AXES.map((a,i)=>`<details><summary>${esc(a.name)} <span>${e.profile[i]===null?'Sin evidencia suficiente':e.profile[i]+' / 100'}</span></summary><p>${esc(a.left)} → ${esc(a.right)}</p><p>${esc(e.rationale[i])}</p>${(e.evidence||[]).filter(v=>v.axis===i).map(v=>{const s=e.sources[v.source];return s?`<p>${link(v.page?s.url.split('#')[0]+'#page='+v.page:s.url,`${s.title}${v.page?' · p. '+v.page:''}`)}</p>`:''}).join('')}</details>`).join('')}`;
 const comparison=e.historical?'':hasScores?axes():'<h2>Datos para comparar</h2><p>Las fuentes de esta ficha documentan su trayectoria. Todavía falta evidencia comparable para asignarle una posición en los ejes del test.</p>';
 shell(esc(e.name),`${portrait(e)}<p class="muted">${esc(e.era||e.period)} · ${esc(e.partyName||e.short||'')}</p><p class="lead">${esc(e.bio||e.summary)}</p>${e.actions?.length?`<h2>Trayectoria y propuestas documentadas</h2><ul>${e.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="notice">${esc(e.comparisonNote)}${hasScores?' Las posturas pueden cambiar con el tiempo. Los números siguientes son estimaciones editoriales.':''}</p>${comparison}<h2>Fuentes públicas</h2>${sourceList(e.sources)}<div class="actions">${profile()&&hasScores?`<a href="#comparar/${party?'partido-':''}${e.id}">Comparar con mis respuestas</a>`:''}<a href="#correcciones">Proponer una corrección con fuentes</a><a href="#${party?'partidos':'figuras'}">Volver al índice</a></div>`);
}

function glossary(){shell('Glosario',`<p>Palabras políticas en contexto uruguayo, sin convertirlas en etiquetas para personas.</p><label class="search-label">Buscar un término<input id="glossary-search" type="search" placeholder="Por ejemplo, liberal o AFAP"></label><div id="glossary-list">${GLOSSARY.map(x=>`<article class="glossary-entry" data-search="${esc((x.term+' '+x.definition).toLocaleLowerCase('es'))}"><h2>${esc(x.term)}</h2><p>${esc(x.definition)}</p></article>`).join('')}</div><p id="search-empty" hidden>No encontramos ese término. Probá con otra palabra.</p>`)}
function history(){shell('Un recorrido por la historia política',`<p>Una selección de hitos para ubicar los debates en su época; no pretende agotar la historia del país.</p><ol class="timeline">${TIMELINE.map(t=>`<li><time>${esc(t.year)}</time><div><h2>${esc(t.title)}</h2><p>${esc(t.text)}</p>${link(t.source.url,t.source.title)}</div></li>`).join('')}</ol>`)}
function methodology(){shell('Cómo funciona este test',`<p class="lead">Tus respuestas forman un perfil. Las decisiones editoriales que lo construyen están a la vista.</p><h2>Lecturas y proyecciones del resultado</h2><p>La lectura general describe hasta tres ejes con una distancia de al menos 10 puntos del centro. El espectro político proyecta economía y seguridad y muestra referentes con evidencia en ambos ejes, sin medir autoritarismo. Las prioridades expresadas describen seis ejes con el mismo umbral. Se muestran los recuentos de respuestas, no porcentajes de confianza.</p><p>Las lecturas ideológicas son cinco prototipos pedagógicos propios sobre cuatro ejes, con sus valores y fórmula visibles. No son perfiles medidos de corrientes reales ni una clasificación de la persona. Las tensiones son reglas exploratorias entre propuestas: no evalúan coherencia lógica ni personalidad.</p><h2>Preguntas y versiones</h2><p>El banco contiene 240 afirmaciones originales, 20 por eje, con una idea principal cada una. Se alternan propuestas orientadas a ambos polos. La Corta usa las primeras 3 de cada eje; la Completa, 5; la Extrema, 20. Las versiones largas profundizan, no cambian los temas.</p><h2>Del acuerdo al puntaje</h2><p>Las cinco opciones valen −2, −1, 0, 1 y 2. Si la afirmación apunta al polo izquierdo, se invierte su signo. En cada eje se calcula la media y se transforma con <strong>50 + 25 × media</strong>. Así, 0 corresponde al polo izquierdo, 100 al derecho y 50 al centro. Se redondea al entero más cercano. Todas las preguntas de un eje pesan igual y ningún eje reemplaza a los demás.</p><h2>Comparación con figuras y partidos</h2><p>La afinidad es <strong>100 − promedio de las diferencias absolutas</strong> entre tus puntajes y los de referencia. Es un índice de proximidad, no una probabilidad. Los empates se ordenan alfabéticamente.</p><p>Esta edición compara ${rankingCount} referentes con cobertura en los mismos cuatro temas. Incluye programas presidenciales, propuestas de precandidaturas, programas de fórmulas y dos referencias de gobierno: Sanguinetti (1995–2000) y Jorge Batlle (2000–2005). También incluye declaraciones públicas de Bergara (2024) y Andrade (2016–2019), identificadas como un tipo de fuente distinto. Las fuentes de cada ficha identifican el documento y el período; las fórmulas con programa compartido pueden empatar. La selección abarca distintas elecciones y no asigna la misma cantidad de referencias a cada partido. Los partidos se comparan por separado, con seis programas de 2024. En las referencias electorales se usan programas; en las de gobierno, leyes y declaraciones del período. Una decisión promulgada no implica autoría exclusiva del presidente ni equivale a una promesa electoral. Estas diferencias limitan la comparación. Ninguna fuente prueba que cada punto fuera una convicción personal. Los puntajes son juicios editoriales orientativos, no números publicados por esas personas.</p><p>Para comparar con la misma cobertura, el ranking usa cuatro ejes documentados en todas las referencias: economía, seguridad, comercio exterior y ambiente. Instituciones y Educación y servicios quedan sin puntaje para los referentes hasta contar con fuentes comparables: no se heredan valores de memoria histórica ni de jubilaciones. Se muestran también las demás ubicaciones disponibles; no entran en ese índice. Las figuras y los partidos pueden obtener el mismo porcentaje porque comparten la referencia programática.</p><h2>Selección y vacíos de evidencia</h2><p>Las ${FIGURES.length} fichas del catálogo pueden aparecer como resultado y en el espectro. Solo se incluyen referentes con los cuatro temas comunes documentados; se retiraron las fichas que no alcanzaban esa cobertura. No se presume qué habrían pensado figuras históricas sobre instituciones posteriores. Los demás ejes sin base suficiente quedan sin puntaje: no se completan con 50.</p><h2>Qué no puede decirte</h2><p>No mide tu identidad, cuánto sabés ni a quién deberías votar. No está validado científicamente. Una respuesta neutra puede reflejar equilibrio, dudas o falta de información; el test no distingue esos motivos. El promedio puede esconder desacuerdos dentro de un eje, por ejemplo, entre educación, salud y cuidados.</p><p>Las fuentes pueden tener sesgos y los programas no equivalen a todas las políticas efectivamente implementadas. La selección de temas, orientación y cifras merece revisión pública. Referencias recopiladas para esta edición: noviembre de 2026; los programas corresponden a elecciones de 2009, 2014, 2019 y 2024; las dos referencias de gobierno abarcan 1995–2000 y 2000–2005; las declaraciones públicas corresponden a 2016–2019 y 2024.</p><div class="actions"><a href="#correcciones">Cuestionar una pregunta o ubicación</a><a href="#faq">Preguntas frecuentes</a></div>`)}
function faq(){shell('Preguntas frecuentes',FAQ.map((f,i)=>`<details><summary>${esc(f.q)}</summary><p>${esc(i===FAQ.length-1?'Usá «Señalar un error» para preparar una observación con una fuente pública. Podés descargarla o abrir un borrador de Issue en GitHub. Solo se envía cuando vos lo publicás allí; GitHub puede pedir una cuenta.':f.a)}</p></details>`).join(''))}
function privacy(){shell('Tus respuestas quedan acá',`<p>El test procesa tus respuestas y calcula el resultado en tu navegador, sin cuentas propias ni envío de tus elecciones a servidores. El alojamiento recibe las solicitudes normales de archivos.</p><h2>Estadísticas de visitas</h2><p>Usamos Cloudflare Web Analytics para conocer las visitas y el rendimiento de la web. Su script envía métricas de navegación y carga a Cloudflare, sin cookies de seguimiento. No enviamos respuestas, puntajes, afinidades políticas ni eventos del cuestionario. La medición automática de cambios de pantalla está desactivada.</p><p>Podés consultar <a href="https://developers.cloudflare.com/web-analytics/about/" target="_blank" rel="noopener noreferrer">cómo funciona Cloudflare Web Analytics</a>.</p><p>El progreso se guarda en este navegador. Otras personas que usen el mismo perfil podrían verlo. El modo privado o las preferencias de almacenamiento pueden impedir que se conserve.</p><p>Las fuentes públicas y GitHub son servicios externos. Se abren solo cuando elegís sus enlaces. Los borradores de correcciones contienen únicamente lo que escribas en el formulario, nunca las respuestas del test.</p><h2>Borrar el avance y resultado</h2><p>Esta acción borra el test actual y las copias de ediciones anteriores guardadas en este navegador; no elimina las estadísticas generales de visitas.</p>${secondary('erase','Borrar mis respuestas')}<p id="erase-status" role="status"></p>`)}
function corrections(){shell('Ayudanos a corregir',`<p>Señalá un error o cuestioná una ubicación con fuentes. No incluyas datos personales ni tus respuestas del test.</p><form id="correction-form"><label>Pregunta, eje o personaje<input name="subject" required maxlength="160" placeholder="Por ejemplo: economía, pregunta sobre ANCAP"></label><label>Qué proponés corregir<textarea name="message" required minlength="15" maxlength="5000" rows="6"></textarea></label><label>Fuente pública (enlace HTTPS)<input name="source" type="url" pattern="https://.*" required maxlength="1500" placeholder="https://"></label><div class="actions"><button class="primary" type="submit">Preparar reporte</button></div></form><div id="correction-output" hidden><h2>Reporte preparado</h2><p>No se envió todavía. Revisalo y elegí si querés publicarlo en GitHub; puede requerir una cuenta.</p><pre id="correction-preview"></pre><div class="actions"><a id="issue-link" target="_blank" rel="noopener noreferrer">Abrir borrador en GitHub</a>${secondary('report-download','Descargar reporte TXT')}</div></div>`)}
function notFound(){shell('No encontramos esa página','<p>Volvé al inicio o explorá la enciclopedia.</p><a href="#inicio">Ir al inicio</a>')}
function render(){const [route,id]=location.hash.slice(1).split('/');const views={inicio:renderHome,iniciar:startScreen,test:testScreen,resultados:resultsDashboard,comparaciones:comparisons,enciclopedia:encyclopedia,figuras:()=>entityList('figuras'),partidos:()=>entityList('partidos'),eje:()=>axisScreen(id),ficha:()=>entityScreen(id),partido:()=>entityScreen(id,true),comparar:()=>compareScreen(id),glosario:glossary,historia:history,metodologia:methodology,faq,privacidad:privacy,correcciones:corrections};(Object.hasOwn(views,route||'inicio')?views[route||'inicio']:notFound)();document.title=`${document.querySelector('h1')?.textContent||'Inicio'} · Uruguay Compass`;window.scrollTo(0,0);if(route&&route!=='inicio')document.querySelector('#main')?.focus({preventScroll:true})}
let reportText='';
document.addEventListener('click',async event=>{const jump=event.target.closest('[data-jump]');if(jump){event.preventDefault();const target=document.getElementById(jump.dataset.jump);if(target?.tagName==='DETAILS')target.open=true;for(let parent=target?.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;target?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});target?.setAttribute('tabindex','-1');target?.focus({preventScroll:true});return}if(event.target.closest('.skip-link')){event.preventDefault();document.querySelector('#main')?.focus();return}const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='start'){selectedVersion=app.querySelector('[name="version"]:checked')?.value||selectedVersion;if(state){go(state.completed?'resultados':'test');return}state={schema:AXIS_SCHEMA,version:selectedVersion,answers:{},cursor:0,completed:false};save();go('test')}
else if(action==='question-context'){const context=document.querySelector('#question-context');context.hidden=!context.hidden;b.setAttribute('aria-expanded',String(!context.hidden))}
else if(action==='auto-advance'){autoAdvance=!autoAdvance;try{localStorage.setItem('compass-auto-advance',String(autoAdvance))}catch{}b.setAttribute('aria-pressed',String(autoAdvance));b.querySelector('strong').textContent=autoAdvance?'Activado':'Desactivado';announce(autoAdvance?'Avance automático activado. Al elegir una respuesta, pasás a la siguiente pregunta.':'Avance automático desactivado. Usá Siguiente para avanzar.')}
else if(action==='previous'){state.cursor=Math.max(0,state.cursor-1);save();testScreen();document.querySelector('#main')?.focus({preventScroll:true});announce(`Pregunta ${state.cursor+1} de ${questionSet(QUESTIONS,state.version).length}`)}
else if(action==='theme'){theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('compass-theme',theme)}catch{}b.innerHTML=themeGraphic();const label=theme==='dark'?'Activar modo claro':'Activar modo oscuro';b.setAttribute('aria-label',label);b.setAttribute('title',label)}
else if(action==='reset'){shell('¿Empezar otro test?',`<p>Tu resultado o avance actual se reemplazará cuando empieces de nuevo. También podés guardar su imagen primero.</p><div class="actions">${secondary('confirm-reset','Sí, empezar de nuevo')}<a href="#${state?.completed?'resultados':'test'}" data-action="cancel-reset">Conservar mi test</a></div>`)}
else if(action==='cancel-reset'){event.preventDefault();go(state?.completed?'resultados':'test')}
else if(action==='confirm-reset'){state=null;try{localStorage.removeItem(KEY)}catch{}go('inicio')}
else if(action==='erase'){state=null;try{localStorage.removeItem(KEY);localStorage.removeItem(OLD_KEY);localStorage.removeItem(ARCHIVE_KEY);document.querySelector('#erase-status').textContent='Respuestas y resultado borrados.'}catch{document.querySelector('#erase-status').textContent='El navegador impidió borrar el almacenamiento. Borrá los datos de este sitio en la configuración del navegador. El perfil ya no se muestra en esta sesión.'}}
else if(action==='download'||action==='share'){try{b.disabled=true;const blob=await resultImage();if(action==='share'&&navigator.canShare?.({files:[new File([blob],'uruguay-compass.png',{type:'image/png'})]})){await navigator.share({files:[new File([blob],'uruguay-compass.png',{type:'image/png'})],title:'Mi perfil · Uruguay Compass'})}else{download(blob,'uruguay-compass.png');document.querySelector('#export-status').textContent=action==='share'?'Este navegador no permite compartir archivos directamente. Descargamos la imagen para que la compartas.':'Imagen guardada. La tarjeta incluye el alcance y los límites de la comparación.'}}catch(e){if(e.name!=='AbortError')document.querySelector('#export-status').textContent='No se pudo crear la imagen. Intentá de nuevo desde un navegador actualizado.'}finally{b.disabled=false}}
else if(action==='report-download')download(new Blob([reportText],{type:'text/plain;charset=utf-8'}),'correccion-compass.txt')});
document.addEventListener('pointermove',event=>{event.target.closest('.answers')?.classList.add('hover-ready')});
function recordAnswer(input){
 const form=document.querySelector('#question-form');if(!state||state.completed||!input.isConnected||input.form!==form)return;
 const value=Number(input.value);if(!validAnswer(value))return;
 const q=questionSet(QUESTIONS,state.version)[state.cursor];state.answers[q.id]=value;save();form.querySelector('button[type="submit"]').disabled=false;if(autoAdvance)form.requestSubmit();
}
document.addEventListener('click',event=>{if(autoAdvance&&event.target.matches('input[name="answer"]'))recordAnswer(event.target)});
document.addEventListener('change',event=>{if(event.target.name==='answer')recordAnswer(event.target);if(event.target.name==='version')selectedVersion=event.target.value});
document.addEventListener('submit',event=>{if(event.target.id==='question-form'){event.preventDefault();const qs=questionSet(QUESTIONS,state.version);if(!validAnswer(state.answers[qs[state.cursor].id]))return;if(state.migrated){if(isComplete(qs,state.answers)){state.completed=true;state.migrated=false;save();go('resultados')}else{state.cursor=qs.findIndex(q=>!validAnswer(state.answers[q.id]));save();testScreen();document.querySelector('#main')?.focus({preventScroll:true})}return}if(state.cursor===qs.length-1){if(!isComplete(qs,state.answers)){state.cursor=qs.findIndex(q=>!validAnswer(state.answers[q.id]));save();testScreen();return}state.completed=true;state.migrated=false;save();go('resultados')}else{state.cursor++;save();testScreen();document.querySelector('#main').focus({preventScroll:true});announce(`Pregunta ${state.cursor+1} de ${qs.length}`)}}if(event.target.id==='correction-form'){event.preventDefault();const fd=new FormData(event.target),subject=String(fd.get('subject')),message=String(fd.get('message')),source=String(fd.get('source'));reportText=`Ficha o pregunta: ${subject}\n\nCorrección propuesta:\n${message}\n\nFuente:\n${source}\n`;document.querySelector('#correction-preview').textContent=reportText;document.querySelector('#issue-link').href=`https://github.com/faacuaramburu/UruguayCompass/issues/new?title=${encodeURIComponent('Corrección: '+subject)}&body=${encodeURIComponent(reportText)}`;document.querySelector('#correction-output').hidden=false;document.querySelector('#correction-output').scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
document.addEventListener('input',event=>{if(!['entity-search','glossary-search'].includes(event.target.id))return;const needle=event.target.value.toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,'');let count=0;for(const row of document.querySelectorAll('[data-search]')){const match=row.dataset.search.normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(needle);row.hidden=!match;if(match)count++}document.querySelector('#search-empty').hidden=count>0});
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
document.addEventListener('change',event=>{
 if(event.target.id==='closest-reference'){
  const chosen=ranked().closest.find(x=>x.entity.id===event.target.value);if(!chosen)return;
  resultReferenceId=chosen.entity.id;resultsDashboard();document.querySelector('#closest-reference')?.focus({preventScroll:true});announce(`Foto y tarjeta: ${chosen.entity.name}. La afinidad no cambió.`);return;
 }
 if(event.target.id!=='insight-reference')return;
 const entity=FIGURES.find(e=>e.id===event.target.value&&e.rankEligible);if(!entity)return;
 const details=comparisonDetails(profile(),entity.profile,ranked().axes);
 const row=x=>`<article class="difference"><div><strong>${esc(AXES[x.axis].name)}</strong><span>Vos ${x.user} · Referencia ${x.reference}</span></div><div class="dual-track"><i style="left:${x.user}%" aria-hidden="true"></i><b style="left:${x.reference}%" aria-hidden="true"></b></div><div class="pole-labels"><span>${esc(AXES[x.axis].left)}</span><span>${esc(AXES[x.axis].right)}</span></div></article>`;
 document.querySelector('#difference-content').innerHTML=`<p>Comparación con <strong>${esc(entity.name)}</strong>. Punto azul: tus respuestas. Círculo vacío: referencia programática.</p><h3>Las distancias más pequeñas</h3>${details.near.map(row).join('')}<h3>Las distancias más grandes</h3>${details.far.length?details.far.map(row).join(''):'<p>Los puntajes coinciden en los cuatro ejes comparados.</p>'}<a href="#comparar/${entity.id}">Ver los doce ejes y sus fuentes</a>`;
 announce(`Comparación actualizada: ${entity.name}`);
});
async function resultImage(){return createResultCard(document.querySelector('#share-preview'),{profile:profile(),axes:AXES,ranking:ranked().ranked,photos:PHOTOS,partyRanking:rankProfiles(profile(),PARTIES).ranked})}

function refreshSpectrum({selectionOnly=false}={}){
 const host=document.querySelector('#spectrum-view'),p=profile();if(!host||!p)return;
 const active=document.activeElement,focusId=active?.dataset?.spectrumPick,wasMarker=active?.classList?.contains('spectrum-marker');
 const next=document.createElement('template');next.innerHTML=renderSpectrumView(p,FIGURES,spectrumState);
 // Keep the identification strip and map mounted across selections
 // to preserve keyboard focus and the browser's scroll anchor.
 host.querySelector('.spectrum-selection').replaceChildren(...next.content.querySelector('.spectrum-selection').childNodes);
 host.querySelector('.spectrum-detail').replaceWith(next.content.querySelector('.spectrum-detail'));
 if(selectionOnly){
  const selectedPoint=next.content.querySelector('.spectrum-marker.is-selected')?.dataset.spectrumPick;
  for(const marker of host.querySelectorAll('.spectrum-marker')){
   const selected=marker.dataset.spectrumPick===selectedPoint;
   marker.classList.toggle('is-selected',selected);marker.setAttribute('aria-pressed',String(selected));
  }
  for(const reference of host.querySelectorAll('.spectrum-reference'))reference.setAttribute('aria-pressed',String(reference.dataset.spectrumPick===spectrumState.selectedId));
 }else{
  host.querySelector('.spectrum-count').replaceChildren(...next.content.querySelector('.spectrum-count').childNodes);
  host.querySelector('.spectrum-graphic').replaceWith(next.content.querySelector('.spectrum-graphic'));
  host.querySelector('.spectrum-catalog').replaceWith(next.content.querySelector('.spectrum-catalog'));
 }
 if(focusId){const candidates=[...host.querySelectorAll('[data-spectrum-pick]')];const next=candidates.find(e=>e.dataset.spectrumPick===focusId&&e.classList.contains('spectrum-marker')===wasMarker);next?.focus({preventScroll:true})}
 announce(host.querySelector('.spectrum-selection').textContent);
}
document.addEventListener('input',event=>{if(event.target.id!=='spectrum-search')return;spectrumState.query=event.target.value;refreshSpectrum()});
document.addEventListener('change',event=>{if(event.target.id!=='spectrum-party')return;spectrumState.party=event.target.value;refreshSpectrum()});
document.addEventListener('click',event=>{
 const pick=event.target.closest('[data-spectrum-pick]');
 if(pick){event.preventDefault();spectrumState.selectedId=pick.dataset.spectrumPick;refreshSpectrum({selectionOnly:true});return}
 if(event.target.closest('[data-spectrum-reset]')){spectrumState.query='';spectrumState.party='all';document.querySelector('#spectrum-search').value='';document.querySelector('#spectrum-party').value='all';refreshSpectrum()}
});
document.addEventListener('keydown',event=>{const point=event.target.closest('.spectrum-marker');if(point&&['Enter',' '].includes(event.key)){event.preventDefault();spectrumState.selectedId=point.dataset.spectrumPick;refreshSpectrum({selectionOnly:true})}});

window.addEventListener('hashchange',render);render();
